
.scroll {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background: var(--jl-paper);
  border: 2px solid var(--jl-gold);
  box-shadow:
    0 4px 20px var(--jl-shadow),
    inset 0 0 60px rgba(201, 169, 110, 0.05);
  font-family: var(--font-body);
  color: var(--jl-ink);
  font-size: 13px;
  line-height: 1.5;
  position: relative;
  overflow: hidden;
}

.scroll::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, transparent 0%, var(--jl-gold) 20%, var(--jl-gold) 80%, transparent 100%);
}

.scroll::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, transparent 0%, var(--jl-gold) 20%, var(--jl-gold) 80%, transparent 100%);
}

.scroll-header {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  background: linear-gradient(180deg, var(--jl-ink) 0%, #2a2a4a 100%);
  cursor: pointer;
  user-select: none;
}

.header-title {
  font-family: var(--font-title);
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--jl-gold);
  letter-spacing: 0.5em;
  text-shadow: 0 0 8px rgba(201, 169, 110, 0.4);
}

.header-deco {
  color: var(--jl-gold-light);
  font-size: 0.8rem;
  opacity: 0.7;
}

.header-deco.left {
  margin-right: auto;
}
.header-deco.right {
  margin-left: auto;
}

.scroll-body {
  animation: unfold 0.3s ease;
}

.content-area {
  padding: 10px 12px 14px;
  min-height: 0;
}

.tab-pane {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-pane.active {
  display: block;
}

@keyframes unfold {
  from {
    opacity: 0;
    max-height: 0;
  }
  to {
    opacity: 1;
    max-height: 2000px;
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
