
.inventory-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.item-card {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid var(--jl-gold-light);
  background: var(--jl-paper);
  border-radius: 2px;
  transition: all 0.2s;

  &:hover {
    transform: translateX(4px);
    border-color: var(--jl-gold);
  }
}

.item-icon {
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--jl-paper-dark);
  border: 1px solid var(--jl-gold-light);
  border-radius: 4px;
  font-size: 1rem;
  flex-shrink: 0;
}

.item-info {
  flex: 1;
  min-width: 0;
}

.item-name {
  display: block;
  font-weight: 700;
  font-size: 0.85rem;
  color: var(--jl-ink);
}

.item-desc {
  display: block;
  font-size: 0.73rem;
  color: var(--jl-ink-faint);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.item-count {
  font-weight: 700;
  font-size: 0.8rem;
  color: var(--jl-gold);
  background: var(--jl-ink);
  padding: 2px 6px;
  border-radius: 3px;
  flex-shrink: 0;
}

.empty-state {
  text-align: center;
  color: var(--jl-ink-faint);
  padding: 20px;
  font-style: italic;
}
