
.user-section {
  padding: 10px 14px;
  border-bottom: 1px solid var(--jl-gold-light);
}

.user-header {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 8px;
}

.user-name {
  font-family: var(--font-title);
  font-size: 1rem;
  font-weight: 700;
  color: var(--jl-ink);
}

.user-basic {
  font-size: 0.78rem;
  color: var(--jl-ink-faint);
}

.user-details {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.detail-item {
  display: flex;
  align-items: center;
  gap: 6px;
}

.detail-label {
  font-size: 0.8rem;
  color: var(--jl-ink-faint);
}

.detail-value {
  font-size: 0.85rem;
  color: var(--jl-ink);
  font-weight: 500;
}

.detail-value.realm {
  color: var(--jl-jade);
  font-weight: 700;
}
